(107166, '_elementor_notifications_data', 'a:2:{s:7:\"timeout\";i:1782936981;s:5:\"value\";s:12640:\"[{\"id\":\"angie-super-community\",\"title\":\"Angie Community Library\",\"description\":\"Browse a library of snippets and widgets built by other Angie users, import any of them into your site, without consuming any credits or remix them with a prompt to match your brief. Every snippet is vetted by the Elementor team. You can also submit your own work for the community to discover.\",\"topic\":\"Angie\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/angie-community.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-angie-community\\/\",\"readMoreText\":\"Browse library\"},{\"id\":\"4.1-atomic-form\",\"title\":\"Generate Atomic Forms\",\"description\":\"Ask Angie to generate forms for lead generation, contact, bookings, promotions and more. Use the new atomic form elements like date picker, radio button, and file upoad.\",\"topic\":\"Atomic Editor\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/41-atomic-form-angie.png\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.1-blog\\/\",\"readMoreText\":\"Learn More\",\"conditions\":[[{\"type\":\"plugin\",\"plugin\":\"elementor-pro\\/elementor-pro.php\"}]]},{\"id\":\"4.1-atomic-form\",\"title\":\"Generate Atomic Forms\",\"description\":\"Ask Angie to generate forms for lead generation, contact, bookings, promotions and more. Use the new atomic form elements like date picker, radio button, and file upoad.\",\"topic\":\"Atomic Editor\",\"imageSrc\":\"https:\\/\\/assets.elementor.com\\/notifications\\/v1\\/images\\/41-atomic-form-angie.png\",\"chipPlan\":\"Pro\",\"chipTags\":[\"Angie\"],\"link\":\"https:\\/\\/go.elementor.com\\/go-pro-notification-4.1-blog\\/\",\"readMoreText\":\"Learn more\",\"cta\":\"Upgrade now\",\"ctaLink\":\"https:\\/\\/go.elementor.com\\/go-pro-notification