(299372, 'wp_statistics_notifications', 'a:3:{s:4:\"data\";a:7:{i:0;a:11:{s:2:\"id\";i:23;s:5:\"title\";s:29:\"New Add-on: Marketing is Here\";s:4:\"icon\";s:14:\"\"\\ud83c\\udfaf\"\";s:11:\"description\";s:166:\"\"<p>Track campaigns, connect to Google Search Console, and set custom goals, now included in your Premium plan. Install the new Marketing add-on for free today.<\\/p>\"\";s:14:\"primary_button\";a:2:{s:5:\"title\";s:11:\"Install Now\";s:3:\"url\";s:50:\"{baseUrl}/wp-admin/admin.php?page=wps_plugins_page\";}s:16:\"secondary_button\";a:2:{s:5:\"title\";s:10:\"Learn More\";s:3:\"url\";s:159:\"https://wp-statistics.com/2025/07/introducing-the-marketing-add-on-gsc-campaigns-goals-more/?utm_source=wp-statistics&utm_medium=link&utm_campaign=notification\";}s:16:\"background_color\";s:7:\"inherit\";s:11:\"plugin_name\";s:13:\"WP Statistics\";s:12:\"activated_at\";s:16:\"2025-07-23T06:00\";s:10:\"expires_at\";N;s:4:\"tags\";a:1:{i:0;s:10:\"is-premium\";}}i:1;a:11:{s:2:\"id\";i:22;s:5:\"title\";s:32:\"Introducing the Marketing Add-on\";s:4:\"icon\";s:14:\"\"\\u2600\\ufe0f\"\";s:11:\"description\";s:108:\"\"Connect to Google Search Console, track custom events and goals, and get insights from your UTM campaigns.\"\";s:14:\"primary_button\";a:2:{s:5:\"title\";s:10:\"Learn More\";s:3:\"url\";s:159:\"https://wp-statistics.com/2025/07/introducing-the-marketing-add-on-gsc-campaigns-goals-more/?utm_source=wp-statistics&utm_medium=link&utm_campaign=notification\";}s:16:\"secondary_button\";a:2:{s:5:\"title\";s:16:\"View Add-on Page\";s:3:\"url\";s:125:\"https://wp-statistics.com/add-ons/wp-statistics-marketing/?utm_source=wp-statistics&utm_medium=link&utm_campaign=notification\";}s:16:\"background_color\";s:7:\"inherit\";s:11:\"plugin_name\";s:13:\"WP Statistics\";s:12:\"activated_at\";s:16:\"2025-07-23T05:51\";s:10:\"expires_at\";N;s:4:\"tags\";a:1:{i:0;s:10:\"no-premium\";}}i:2;a:11:{s:2:\"id\";i:21;s:5:\"title\";s:28:\"WP Statistics 14.15 is here!\";s:4:\"icon\";s:14:\"\