(1852, 424, '_form', '<div class=\"row\"><div class=\"col-md-4\"><div class=\"input-item input-item-name ltn__custom-icon\">\n[text* Enteryourname placeholder \"Enter your name\"]</div></div>\n<div class=\"col-md-4\"><div class=\"input-item input-item-email ltn__custom-icon\">[email* email-648 placeholder \"Enter email address\"]</div></div><div class=\"col-md-4\">\n<div class=\"input-item\">[text* Enterphonenumber placeholder \"Enter phone number\"]</div></div>\n<div class=\"col-md-6\"><div class=\"input-item input-item-phone ltn__custom-icon\">[select* jobtitle \"Select Job Title by City\" \"Area Sales Manager\"]</div></div><div class=\"col-md-6\"><div class=\"input-item input-item-phone ltn__custom-icon\">[select location \"Select Location\" \"Nashik\" \"Mumbai\" \"Nagpur\" \"Aurangabad\"]</div></div>\n\n   <div class=\"col-md-6\">\n      <div class=\"input-item input-item-phone ltn__custom-icon\">[select* jobtitle \"Select Job Title by State\"  \"Territory/State  Area Sales Manager\"]</div>\n   </div>\n   <div class=\"col-md-6\">\n      <div class=\"input-item input-item-phone ltn__custom-icon\">[select location \"Select Location\"  \"Maharashtra\" \"Rajasthan\" \"UP\" \"Delhi\"]</div>\n   </div>\n\n\n</div>\n<div class=\"col-md-6\">\n<div class=\"input-item input-item-textarea\">Upload Your CV [file* cv filetypes:pdf|doc|docx]</div>\n<div class=\"input-item input-item-textarea\">[recaptcha]</div>\n<div class=\"btn-wrapper mt-0\"><button class=\"btn theme-btn-1 btn-effect-1 text-uppercase\" type=\"submit\">submit</button></div>'),
(1853, 424, '_mail', 'a:9:{s:6:\"active\";b:1;s:7:\"subject\";s:6:\"Career\";s:6:\"sender\";s:47:\"[Enteryourname] <wordpress@jadespaceglobal.com>\";s:9:\"recipient\";s:26:\"career@jadespaceglobal.com\";s:4:\"body\";s:90:\"Name : [Enteryourname]\nEmail : [email-648]\nJob Title: [jobtitle]\nPhone: [Enterphonenumber]\";s:18:\"additional_headers\";s:21:\"Reply-To: [email-648]\";s:11:\"attachments\";s:4:\"[cv]\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
(1854, 424, '_mail_2', 'a:9:{s:6:\"active\";b:0;s:7:\"subject\";s:30:\"[_site_title] \"[your-subject]\"\";s:6:\"sender\";s:45:\"[_site_title] <wordpress@jadespaceglobal.com>\";s:9:\"recipient\";s:12:\"[your-email]\";s:4:\"body\";s:220:\"Message Body:\n[your-message]\n\n-- \nThis email is a receipt for your contact form submission on our website ([_site_title] [_site_url]) in which your email address was used. If that was not you, please ignore this message.\";s:18:\"additional_headers\";s:29:\"Reply-To: [_site_admin_email]\";s:11:\"attachments\";s:0:\"\";s:8:\"use_html\";b:0;s:13:\"exclude_blank\";b:0;}'),
