(43, 'woocommerce-WCSubscriptions-June-2023-updated-needed', 'marketing', 'en_US', 'Action required: Security update of WooCommerce Subscriptions', '<strong>Your store requires a security update for the WooCommerce Subscriptions plugin</strong>. Please update the WooCommerce Subscriptions plugin immediately to address a potential vulnerability.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(44, 'woocommerce-WCReturnsWarranty-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce Returns and Warranty Requests extension', '<strong>Your store requires a security update for the Returns and Warranty Requests extension</strong>.  Please update to the latest version of the WooCommerce Returns and Warranty Requests extension immediately to address a potential vulnerability discovered on May 31.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(45, 'woocommerce-WCOPC-June-2023-updated-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce One Page Checkout', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce One Page Checkout extension</strong>. The fix for this vulnerability was released for this extension on June 13th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(46, 'woocommerce-WCGC-July-2023-update-needed', 'update', 'en_US', 'Action required: Security update of WooCommerce GoCardless Extension', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce GoCardless extension</strong>. The fix for this vulnerability was released on July 4th. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(47, 'woocommerce-shipping-fedex-api-outage-2023-07-16', 'warning', 'en_US', 'Scheduled FedEx API outage — July 2023', 'On July 16 there will be a full outage of the FedEx API from 04:00 to 08:00 AM UTC. Due to planned maintenance by FedEx, you\'ll be unable to provide FedEx shipping rates during this time. Follow the link below for more information and recommendations on how to minimize impact.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(48, 'wcship-2023-07-hazmat-update-needed', 'update', 'en_US', 'Action required: USPS HAZMAT compliance update for WooCommerce Shipping & Tax extension', '<strong>Your store requires an update for the WooCommerce Shipping extension</strong>. Please update to the latest version of the WooCommerce Shipping &amp; Tax extension immediately to ensure compliance with new USPS HAZMAT rules currently in effect.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(49, 'woocommerce-WCStripe-Aug-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe plugin', '<strong>Your shop requires an important security update for the  WooCommerce Stripe plugin</strong>. The fix for this vulnerability was released on July 31. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(50, 'woocommerce-WCStripe-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooCommerce Stripe plugin', '<strong>Your store has been updated to the latest secure version of the WooCommerce Stripe plugin</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(51, 'woocommerce-WooPayments-Aug-2023-security-updated', 'update', 'en_US', 'Security update of WooPayments (WooCommerce Payments) plugin', '<strong>Your store has been updated to the more secure version of WooPayments (WooCommerce Payments)</strong>. This update was released on July 31.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(52, 'avalara_q3-2023_noAvaTax', 'marketing', 'en_US', 'Automatically calculate VAT in real time', 'Take the effort out of determining tax rates and sell confidently across borders with automated tax management from Avalara AvaTax— including built-in VAT calculation when you sell into or across the EU and UK. Save time and stay compliant when you let Avalara do the heavy lifting.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(53, 'woo-activation-survey-blockers-22AUG23', 'info', 'en_US', 'How can we help you get that first sale?', 'Your feedback is vital. Please take a minute to share your experience of setting up your new store and whether anything is preventing you from making those first few sales. Together, we can make Woo even better!', '{}', 'unactioned', 'woocommerce.com', '2024-06-30 17:37:35', NULL, 0, 'plain', '', 0, 0, 'info'),
(54, 'woocommerce-usermeta-Sept2023-productvendors', 'update', 'en_US', 'Your store requires a security update', '<strong>Your shop needs an update to address a vulnerability in WooCommerce.</strong> The fix was released on Sept 15. Please update WooCommerce to the latest version immediately. <a href=\"https://developer.woocommerce.com/2023/09/16/woocommerce-vulnerability-reintroduced-from-7-0-1/\" />Read our developer update</a> for more information.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(55, 'woocommerce-STRIPE-Oct-2023-update-needed', 'update', 'en_US', 'Action required: Security update for WooCommerce Stripe Gateway', '<strong>Your shop requires a security update to address a vulnerability in the WooCommerce Stripe Gateway</strong>. The fix for this vulnerability was released on October 17. Please update immediately.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(56, 'amazon-mcf-reviews-2023-12-07', 'marketing', 'en_US', 'Enjoying Amazon MCF for WooCommerce?', 'We\'re Never Settle, the developers behind Amazon MCF for WooCommerce, and would be deeply honored to have your review. Reviews help immensely as other users can learn how MCF can solve their needs too! Not happy or need help? Please reach out for support and we’d love to make things right!', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(57, 'remove_estimated_deposits_2024', 'marketing', 'en_US', 'Estimated deposits are going away', 'To provide more accurate deposit information and support the expansion of instant deposits, estimated deposit details will no longer be available in WooPayments. We recommend upgrading to the latest version of WooPayments for more detailed balance status information.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(58, 'woocommerce-payfast-may-2024-update-needed', 'update', 'en_US', 'An important update is required for the Payfast Payment Gateway', '<strong>Please update to the latest version of the Payfast Payment Gateway for WooCommerce immediately to address a security vulnerability</strong>. This update is required to ensure that your transactions continue to process.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(59, 'checkout_block_update_july_2024', 'marketing', 'en_US', 'UPDATE: The checkout block is getting an upgrade!', 'We’re improving the checkout block in 2024, starting with WooCommerce 9.0, launching on June 18! The latest release includes streamlined order summary with sticky functionality, better address form layout, and other enhancements to boost conversion.', '{}', 'pending', 'woocommerce.com', '2024-06-21 17:37:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(60, 'wc-admin-wc-helper-connection', 'info', 'en_US', 'Connect to WooCommerce.com', 'Connect to get important product notifications and updates.', '{}', 'unactioned', 'woocommerce-admin', '2024-06-21 17:37:38', NULL, 0, 'plain', '', 0, 1, 'info'),
(62, 'wc-admin-launch-checklist', 'info', 'en_US', 'Ready to launch your store?', 'To make sure you never get that sinking \"what did I forget\" feeling, we\'ve put together the essential pre-launch checklist.', '{}', 'unactioned', 'woocommerce-admin', '2024-06-22 17:47:20', NULL, 0, 'plain', '', 0, 0, 'info'),
(63, 'wc-admin-customizing-product-catalog', 'info', 'en_US', 'How to customize your product catalog', 'You want your product catalog and images to look great and align with your brand. This guide will give you all the tips you need to get your products looking great in your store.', '{}', 'unactioned', 'woocommerce-admin', '2024-06-23 17:38:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(64, 'wc-admin-mobile-app', 'info', 'en_US', 'Install Woo mobile app', 'Install the WooCommerce mobile app to manage orders, receive sales notifications, and view key metrics — wherever you are.', '{}', 'unactioned', 'woocommerce-admin', '2024-06-23 17:38:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(65, 'wc-admin-onboarding-payments-reminder', 'info', 'en_US', 'Start accepting payments on your store!', 'Take payments with the provider that’s right for you - choose from 100+ payment gateways for WooCommerce.', '{}', 'unactioned', 'woocommerce-admin', '2024-06-26 18:28:13', NULL, 0, 'plain', '', 0, 0, 'info'),
(68, 'bfcm-survey-jul2024', 'marketing', 'en_US', 'Complete our holiday survey and get a $30 coupon', 'We want to understand how you prepare your store for Black Friday/Cyber Monday and the holidays.\r\n\r\nComplete our 10-minute survey and get $30 USD off an extension from our official Marketplace. Hurry, the survey closes July 15.', '{}', 'pending', 'woocommerce.com', '2024-07-04 17:38:49', NULL, 0, 'plain', '', 0, 0, 'info'),
(69, 'stripe_newcheckout_q3_2024', 'marketing', 'en_US', 'Upgrade your Stripe checkout for even more payment options', 'Boost sales, increase order value, and reach new customers with the new checkout from Stripe. Support 23 payment methods, including buy now, pay later methods like Klarna, Afterpay, and Affirm; Bancontact in Europe and Alipay in Asia; and Link, an accelerated checkout experience that autofills payment information.', '{}', 'pending', 'woocommerce.com', '2024-07-04 17:38:49', NULL, 0, 'plain', '', 0, 0, 'info'),
(70, 'klaviyo_q4_2024', 'marketing', 'en_US', 'Need a marketing solution to help you sell more?', 'Over 13,000 brands use Klaviyo to grow faster. You can drive 46x ROI with their personalized email, SMS, forms, and product reviews. Start for free today.', '{}', 'pending', 'woocommerce.com', '2024-07-31 17:39:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(71, 'wc-update-db-reminder', 'update', 'en_US', 'WooCommerce database update required', 'WooCommerce has been updated! To keep things running smoothly, we have to update your database to the newest version. The database update process runs in the background and may take a little while, so please be patient. Advanced users can alternatively update via <a href=\"https://github.com/woocommerce/woocommerce/wiki/Upgrading-the-database-using-WP-CLI\">WP CLI</a>.', '{}', 'actioned', 'woocommerce-core', '2024-08-09 16:48:53', NULL, 0, 'plain', '', 1, 0, 'info'),
(72, 'wnww-recap-july', 'marketing', 'en_US', 'Powerful updates and upgrades in WooCommerce', 'Have you seen all the latest from Woo? Check out our recent roundup for a look at the newest features, extensions, and insights making WooCommerce perform better than ever.', '{}', 'pending', 'woocommerce.com', '2024-08-13 18:16:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(74, 'bfcm2024-landing-page', 'marketing', 'en_US', 'The best way to prepare for holiday success', 'The upcoming holiday season is the busiest time of the year for many online stores. We want to help you make the most of it with an early gift: our first-ever Black Friday Cyber Monday Trends Report. It\'s full of stats, trends, and recommendations to knock your holiday socks off!', '{}', 'pending', 'woocommerce.com', '2024-09-04 17:41:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(76, 'stripe_securityupdate_q3_2024', 'update', 'en_US', 'Security update required for your Stripe extension', 'To continue securely accepting payments, you must update your Stripe extension to at least version 8.6, re-authenticate, and turn on the new checkout experience. Review the documentation for instructions on how to make the necessary changes from your WooCommerce dashboard.', '{}', 'pending', 'woocommerce.com', '2024-09-18 17:56:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(77, 'wc-admin-real-time-order-alerts', 'info', 'en_US', 'Get real-time order alerts anywhere', 'Get notifications about store activity, including new orders and product reviews directly on your mobile devices with the Woo app.', '{}', 'unactioned', 'woocommerce-admin', '2024-09-19 17:39:05', NULL, 0, 'plain', '', 0, 0, 'info'),
(78, 'paypal_migration_Q3_2024', 'marketing', 'en_US', 'You’re using an outdated version of PayPal', 'Don\'t miss out on potential sales this holiday season — upgrade your store\'s checkout experience by switching to the all-in-one PayPal Payments extension. Enable customers to pay using Venmo and Pay Later (where available), credit and debit cards, Apple Pay, Google Pay, and country-specific options.', '{}', 'pending', 'woocommerce.com', '2024-10-04 17:39:17', NULL, 0, 'plain', '', 0, 0, 'info'),
(79, 'mollie_q4_2024', 'marketing', 'en_US', 'Special offer: Zero transaction fees for your first month with Mollie', 'With seamless checkout, flexible financing, and 30+ local and global payment methods, Mollie is the all-in-one payment solution that enhances the customer experience and helps your business grow. Start your account today and enjoy ZERO transaction fees for the first month. Ts&amp;Cs apply.', '{}', 'pending', 'woocommerce.com', '2024-10-31 17:45:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(80, 'paypal_migration_Q3_2024_v2', 'marketing', 'en_US', 'You’re using an outdated version of PayPal', 'Don\'t miss out on potential sales this holiday season — upgrade your store\'s checkout experience by switching to the all-in-one PayPal Payments extension. Enable customers to pay using Venmo and Pay Later (where available), credit and debit cards, Apple Pay, Google Pay, and country-specific options.', '{}', 'pending', 'woocommerce.com', '2024-10-31 17:45:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(83, 'Renewal_notification_emails_Woosubscriptions_Nov2024', 'marketing', 'en_US', 'WooCommerce Subscriptions just got even better', 'You can now send automatic email reminders to customers before their subscriptions renew or expire. To enable this for your store, update to the latest version of WooCommerce Subscriptions (don\'t forget to make a backup first) and follow the steps linked below.', '{}', 'pending', 'woocommerce.com', '2024-11-19 17:37:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(84, 'paypal_promo_Q4_2024', 'marketing', 'en_US', 'Add PayPal to your existing checkout this holiday season', 'Drive conversion and give customers more confidence to buy when you complement your checkout with PayPal, Venmo, Pay Later, and more. Attract new shoppers and give them a streamlined buying experience with Fastlane, PayPal’s fast and simple guest checkout.', '{}', 'pending', 'woocommerce.com', '2024-11-27 17:40:12', NULL, 0, 'plain', '', 0, 0, 'info'),
(85, 'sirt-woo-2024-11-xss-admin', 'update', 'en_US', 'An important update is required for WooCommerce', 'This update addresses a security vulnerability that could allow unauthorized access to administrative privileges on your site. <a href=\"https://developer.woocommerce.com/2024/12/03/woocommerce-9-4-3-and-woocommerce-9-3-4-available-now/\">Learn more</a>.\r\n<br><br>\r\n<strong>Please ensure your site is updated to the latest version to stay secure.</strong>', '{}', 'pending', 'woocommerce.com', '2024-12-04 17:41:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(86, 'usps-mail-service-to-canada-suspended-dec-2024', 'update', 'en_US', 'Please note: USPS Mail Service to Canada Suspended', 'The United States Postal Service has temporarily suspended mail service to Canada due to the ongoing Canadian postal workers\' strike. USPS is asking users to refrain from mailing items to Canada at this time.', '{}', 'pending', 'woocommerce.com', '2024-12-05 17:50:45', NULL, 0, 'plain', '', 0, 0, 'info'),
(87, 'Announce-UPS-WCShipping-Dec2024', 'marketing', 'en_US', 'WooCommerce Shipping now supports select UPS services', 'Give customers the power and reliability of UPS, directly from your dashboard. Access discounted rates, convenient shipping options, and fast, on-time delivery with UPS on WooCommerce Shipping — and stay tuned for UPS® Ground Saver rates coming in 2025.', '{}', 'pending', 'woocommerce.com', '2024-12-12 17:51:43', NULL, 0, 'plain', '', 0, 0, 'info'),
(88, 'wc-admin-manage-orders-on-the-go', 'info', 'en_US', 'Manage your orders on the go', 'Look for orders, customer info, and process refunds in one click with the Woo app.', '{}', 'unactioned', 'woocommerce-admin', '2024-12-18 17:46:33', NULL, 0, 'plain', '', 0, 0, 'info'),
(89, 'account-creation-after-checkout-dec2024', 'marketing', 'en_US', 'Offer account creation after checkout', 'Your customers can now create accounts after they check out on block-based themes. Enable the new “After checkout” block in your account settings and enjoy smoother guest checkout, better conversion, and more repeat business.', '{}', 'pending', 'woocommerce.com', '2024-12-18 17:46:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(90, 'woocommerce-analytics-order-attribution-promotions-december-2024', 'marketing', 'en_US', 'Discover what drives your sales', 'Use our powerful <strong>Order Attribution</strong> extension to understand what truly drives your revenue. Track your sales journey, identify your most effective marketing channels, and optimize your sales strategy.', '{}', 'unactioned', 'woocommerce.com', '2025-02-24 17:37:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(91, 'affirm_promo_Q1_2025', 'marketing', 'en_US', 'Save up to 50% on merchant fees with Affirm', 'Kickstart the year with buy now, pay later and get merchant rates as low as 2.9% + 30¢ per transaction for 30 days. Download the extension and complete your application from your WooCommerce dashboard by February 19, 2025 to claim the offer. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2025-01-20 17:52:20', NULL, 0, 'plain', '', 0, 0, 'info'),
(92, 'new-woo-brand-announcement-feb4-2025', 'marketing', 'en_US', 'Meet the new Woo', 'WooCommerce has a new look, but underneath, we’re still the same customizable, open-source ecommerce platform you know and love. Plus, we’ve got some major improvements to our platform and product on the way.', '{}', 'pending', 'woocommerce.com', '2025-02-04 17:38:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(93, 'paypal_bnpl_au_promo_Q1_2025', 'marketing', 'en_US', 'Australian shoppers can Pay in 4 with PayPal', 'Enable Pay in 4 messaging to let Australian customers know that they can pay over time while you get paid up front and in full. Pay in 4 is included in PayPal Payments at no additional cost. Eligible buyers can pay in four interest-free payments for purchases of $30 to $2,000 AUD. Terms apply.', '{}', 'pending', 'woocommerce.com', '2025-02-12 17:56:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(94, 'stripe_stripetax_q1_2025', 'marketing', 'en_US', 'Say goodbye to your tax woes', 'Stripe Tax automatically applies the correct sales tax, VAT, or GST, saving time while keeping you compliant. And with simple automatic filing, you can stop stressing at tax time and focus on growing instead.', '{}', 'pending', 'woocommerce.com', '2025-02-19 17:40:41', NULL, 0, 'plain', '', 0, 0, 'info'),
(95, 'printful_promo_q1_2025', 'marketing', 'en_US', 'New: sell print-on-demand products, risk-free', 'Expand your product line with Printful, now available in the WooCommerce Marketplace. Sell custom products with no upfront costs or inventory. This trusted supplier prints, packages, and ships for you, so you can focus on growing your store — and your next big idea.', '{}', 'pending', 'woocommerce.com', '2025-02-26 17:53:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(96, 'paypal-braintree-sdk-depreciation-2025-02-20', 'update', 'en_US', 'Update required for your PayPal Braintree extension', 'To continue securely accepting payments, you must update your PayPal Braintree extension to version 3.2.4 or newer before June 30, 2025. Your current extension version will not support payment processing after this date due to an SSL certificate update.', '{}', 'pending', 'woocommerce.com', '2025-03-04 17:39:45', NULL, 0, 'plain', '', 0, 0, 'info'),
(97, 'woo-marketplace-two-year-subscriptions-rin-2025-03-17', 'marketing', 'en_US', 'Save 20% on new two-year subscriptions', 'We’ve introduced 20% off two-year subscriptions for all products* in the WooCommerce Marketplace. Lock in long-term savings and make sure your store never misses a beat. \r\n\r\n*Some exclusions apply. New purchases only.', '{}', 'pending', 'woocommerce.com', '2025-03-17 17:57:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(98, 'wc-admin-performance-on-mobile', 'info', 'en_US', 'Track your store performance on mobile', 'Monitor your sales and high performing products with the Woo app.', '{}', 'unactioned', 'woocommerce-admin', '2025-03-18 17:50:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(100, 'viva_wallet_migration_q1_2025', 'update', 'en_US', 'Switch to the new Viva.com Smart Checkout', 'The Viva Wallet extension is no longer being updated and improved. To get the best Viva.com experience, move to the new Smart Checkout. It’s fast, secure, and fully compatible with the latest WooCommerce features.', '{}', 'pending', 'woocommerce.com', '2025-04-03 17:40:50', NULL, 0, 'plain', '', 0, 0, 'info'),
(101, 'stripe_orderstatus_bug_q2_2025', 'update', 'en_US', 'Action Required: Update Order Status Manager', 'Update to the latest Order Status Manager (v1.15.5+) to ensure payments are captured. Your version of WooCommerce Order Status Manager can interfere with order processing for payment gateways (including WooCommerce Stripe Gateway v9.2.0+), which may cause orders to process without capturing payment.', '{}', 'pending', 'woocommerce.com', '2025-04-03 17:40:50', NULL, 0, 'plain', '', 0, 0, 'info'),
(102, 'WooCommerce-Stripe-Gateway-Update-April-2025', 'update', 'en_US', 'Action required: Update WooCommerce Stripe Gateway to v9.4.1', '<strong>An important update for WooCommerce Stripe Payment Gateway has been released</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. Please update as soon as possible for optimal store performance. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-04-19 17:41:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(103, 'WooCommerce-Stripe-Gateway-Update-Info-April-2025', 'update', 'en_US', 'WooCommerce Stripe Gateway has been updated to v9.4.1', '<strong>WooCommerce Stripe Payment Gateway was recently updated</strong>. Version 9.4.1 addresses performance issues and payment method visibility problems that occurred in version 9.4.0. No further action is required. Please read <a href=\"https://developer.woocommerce.com/2025/04/18/https://developer.woocommerce.com/2025/04/18/developer-advisory-stripe-payment-gateway-9-4-1-release/\" /> this advisory post </a>for more information.', '{}', 'pending', 'woocommerce.com', '2025-04-19 17:41:57', NULL, 0, 'plain', '', 0, 0, 'info'),
(104, 'klaviyo_q2_2025', 'marketing', 'en_US', 'Tailor your marketing with data-driven automation', 'Deliver personalized experiences at scale, simplify your stack, and make your data work for you using Klaviyo’s best-in-class marketing extension for Woo. With advanced segmentation based on actual customer behavior, you can send email and SMS messages that drive revenue and increase loyalty — without adding complexity', '{}', 'pending', 'woocommerce.com', '2025-04-30 17:44:18', NULL, 0, 'plain', '', 0, 0, 'info'),
(105, 'uk-vat-notice-2025-04-30', 'warning', 'en_US', 'UK VAT numbers are no longer supported', 'Due to recent HM Revenue &amp; Customs (HMRC) VAT API changes, your EU VAT Number for WooCommerce extension can no longer validate UK VAT numbers. HMRC now requires merchants to register an API key, which this extension does not currently support. We recommend EU/UK VAT Validation Manager for WooCommerce as a replacement', '{}', 'pending', 'woocommerce.com', '2025-05-05 17:44:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(106, 'payson-retirement-2025', 'update', 'en_US', 'Payson Form Retirement', 'Svea Bank is discontinuing the Payson service; the last date for transactions is August 31, 2025. As a result, the Payson Form extension has been removed from WooCommerce.com. Documentation remains available.', '{}', 'pending', 'woocommerce.com', '2025-05-13 17:46:30', NULL, 0, 'plain', '', 0, 0, 'info'),
(107, 'wc-admin-new-sales-record', 'info', 'en_US', 'New sales record!', 'Woohoo, May 18th was your record day for sales! Net sales was ₹527,380.00 beating the previous record of ₹360,000.00 set on March 24th.', '{\"old_record_date\":\"2025-03-24\",\"old_record_amt\":360000,\"new_record_date\":\"2025-05-18\",\"new_record_amt\":527380}', 'unactioned', 'woocommerce-admin', '2025-05-19 17:56:07', NULL, 0, 'plain', '', 0, 0, 'info'),
(108, 'paypal_q2_2025', 'marketing', 'en_US', 'Power up sales with Pay Later messaging', 'Help increase your sales and grow cart sizes by letting customers know they have flexible payment options. Merchants see up to an 11% sales lift when they add Pay Later messaging — plus, it integrates seamlessly with your PayPal checkout.', '{}', 'pending', 'woocommerce.com', '2025-05-22 17:56:33', NULL, 0, 'plain', '', 0, 0, 'info'),
(109, 'paypal-braintree-sdk-depreciation-2025-05-30', 'update', 'en_US', 'Action required: Update the PayPal Braintree extension', 'Your PayPal Braintree extension is using an outdated SDK and will stop processing payments after June 30, 2025, due to a root SSL certificate expiration. To avoid service disruption, update to version 3.2.4 or newer immediately.', '{}', 'pending', 'woocommerce.com', '2025-05-29 17:41:59', NULL, 0, 'plain', '', 0, 0, 'info'),
(110, 'tento_q2_2025', 'marketing', 'en_US', 'Get your free business credit score', 'Strong business credit is the key to better deals, stronger partnerships, and sustainable growth. Tento Business Credit Monitoring helps you catch risks early, secure better financing, and fuel smarter growth — with no impact to your credit.', '{}', 'pending', 'woocommerce.com', '2025-06-04 17:46:54', NULL, 0, 'plain', '', 0, 0, 'info'),
(111, 'wc-admin-edit-products-on-the-move', 'info', 'en_US', 'Edit products on the move', 'Edit and create new products from your mobile devices with the Woo app', '{}', 'unactioned', 'woocommerce-admin', '2025-06-21 17:57:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(112, 'woopayments-multibanco-alipay-wechat-launch-2025-06-23', 'marketing', 'en_US', 'Multibanco, AliPay and WeChat now available in WooPayments', 'Multibanco, AliPay, and WeChat Pay are now available in WooPayments! Offer trusted local payment methods to customers in key global markets and boost international sales. Geo restrictions apply.', '{}', 'pending', 'woocommerce.com', '2025-06-23 17:54:06', NULL, 0, 'plain', '', 0, 0, 'info'),
(113, 'woopayments-new-lpms-2025-06-30', 'marketing', 'en_US', 'Get the POS built specifically for Woo stores', 'Introducing WooCommerce POS, our new point-of-sale solution built to get you up and running quickly with in-person sales. Search products, scan barcodes, apply coupons, and send email receipts — right in the WooCommerce mobile app, with all of your online and physical sales synced in real time — no extra setup required', '{}', 'pending', 'woocommerce.com', '2025-06-30 18:18:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(114, 'tiktok-webinar-promo-july2025', 'marketing', 'en_US', 'You\'re Invited: TikTok for WooCommerce Webinar', 'Join us for a free webinar with our friends at TikTok on Tuesday, July 8, at 4 pm UTC. We\'ll cover creative tips and best practices for making content that turns views into sales.', '{}', 'pending', 'woocommerce.com', '2025-06-30 18:18:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(115, 'woopayments-grabpay-launch-2025-07-07', 'marketing', 'en_US', 'GrabPay now available in WooPayments', 'Offer GrabPay through WooPayments and make checkout easier for customers across Southeast Asia. Enable it today and expand your reach with a payment method they know and trust.', '{}', 'pending', 'woocommerce.com', '2025-07-07 17:41:54', NULL, 0, 'plain', '', 0, 0, 'info'),
(116, 'BFCM-25-Survey', 'marketing', 'en_US', 'You’re invited: Take our quick BFCM survey and get 25% off', 'We’re gathering insights on how businesses prepare for peak sales moments like Black Friday and Cyber Monday — so we can better support you. Take our quick 8-minute survey to share your thoughts and get 25% off your next WooCommerce extension as a thank you.', '{}', 'pending', 'woocommerce.com', '2025-07-14 17:43:01', NULL, 0, 'plain', '', 0, 0, 'info');
INSERT INTO `ja_wc_admin_notes` (`note_id`, `name`, `type`, `locale`, `title`, `content`, `content_data`, `status`, `source`, `date_created`, `date_reminder`, `is_snoozable`, `layout`, `image`, `is_deleted`, `is_read`, `icon`) VALUES
(117, 'woohoo10-coupon', 'marketing', 'en_US', 'Celebrate and save with WooCommerce 10.0', 'To mark this milestone release, get 10% off extensions and themes in the official Woo Marketplace. Use code WOOHOO10 at checkout to save on essential tools that help grow your business. Offer ends August 15, 2025. Terms and conditions apply.', '{}', 'unactioned', 'woocommerce.com', '2025-07-21 17:39:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(118, 'paypaladvantage_q3_2025', 'marketing', 'en_US', 'Add PayPal Checkout and earn up to $1,000*', 'PayPal Checkout can boost conversion by up to 46% and average order value by up to 62% with no disruption to your checkout. New US merchants who activate by August 31 save 25% on transaction fees for 6 months. Excludes Venmo. Terms apply.*', '{}', 'pending', 'woocommerce.com', '2025-07-23 17:40:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(119, 'stripe_optimizedcheckout_upgrade_q3_2025', 'marketing', 'en_US', 'Upgrade for a faster, more flexible Stripe checkout', 'You\'re not on the latest WooCommerce Stripe Payment Gateway version. Upgrade to version 9.8 to access Stripe\'s Optimized Checkout Suite and leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.', '{}', 'pending', 'woocommerce.com', '2025-08-13 17:45:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(120, 'stripe_optimizedcheckout_enable_q3_2025', 'marketing', 'en_US', 'Unlock dynamic payments and sell more', 'You’re on the latest WooCommerce Stripe Payment Gateway — now unlock its full potential by enabling the Optimized Checkout Suite. It uses AI models to dynamically surface the most relevant payment methods for each customer, helping you boost conversions.', '{}', 'pending', 'woocommerce.com', '2025-08-13 17:45:36', NULL, 0, 'plain', '', 0, 0, 'info'),
(121, 'stripe_optimizedcheckout_promotion_q3_2025', 'marketing', 'en_US', 'Upgrade to Stripe for a faster, more flexible checkout', 'Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Leverage AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click Link checkout.', '{}', 'pending', 'woocommerce.com', '2025-08-15 17:41:11', NULL, 0, 'plain', '', 0, 0, 'info'),
(122, 'woo-subscription-gifting-bundling-2025-08-18', 'marketing', 'en_US', 'Grow recurring revenue with gifting', 'WooCommerce Subscriptions now includes gifting. Customers can buy subscriptions for others, helping you reach new shoppers and grow recurring revenue with less effort. Update to the latest version of Subscriptions (7.8.0) to start offering gifting.', '{}', 'pending', 'woocommerce.com', '2025-08-20 17:43:31', NULL, 0, 'plain', '', 0, 0, 'info'),
(123, 'stripe_optimizedcheckout_competitors_q3_2025', 'marketing', 'en_US', 'Upgrade to the official WooCommerce Stripe Payment Gateway', 'Unlock dynamic payments with Stripe’s Optimized Checkout Suite — now available with the WooCommerce Stripe Payment Gateway. Use AI models to dynamically surface the most relevant payment methods for each customer, including BNPL, local options, and one-click checkout with Link.', '{}', 'pending', 'woocommerce.com', '2025-08-28 18:37:28', NULL, 0, 'plain', '', 0, 0, 'info'),
(124, 'UPS-promo-RIN-WCS-Aug-25', 'marketing', 'en_US', 'Get up to $100 off your first UPS shipments', 'For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.', '{}', 'pending', 'woocommerce.com', '2025-09-10 17:41:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(125, 'UPS-promo-RIN-WCST-Aug-25', 'marketing', 'en_US', 'Get up to $100 off your first UPS shipments', 'For a limited time, merchants new to UPS can get up to $10 off their first 10 UPS labels on WooCommerce Shipping. Simplify your shipping, lower costs, and keep customers happy with fast, affordable options built right into your store dashboard.', '{}', 'pending', 'woocommerce.com', '2025-09-10 17:41:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(126, 'square_ordersync_upgrade_q3_2025', 'marketing', 'en_US', 'You asked, we delivered — order sync is here for Square', 'Update your Square extension to v5.0 to access <a href=\"https://woocommerce.com/document/woocommerce-square/sync-settings/sync-orders-between-woocommerce-and-square/\">automatic order syncing</a>. Manage your online sales in Square, keep reports accurate, and save time with order updates visible across both platforms.', '{}', 'pending', 'woocommerce.com', '2025-09-11 17:42:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(127, 'klaviyo_q3_2025', 'marketing', 'en_US', 'Smarter marketing starts with Woo x Klaviyo', 'Personalize every customer interaction with Klaviyo, Woo\'s preferred marketing automation solution. Advanced segmentation based on real customer behavior lets you create email and SMS campaigns focused on driving loyalty and revenue. So you can grow sales while simplifying your stack.', '{}', 'pending', 'woocommerce.com', '2025-09-17 17:41:44', NULL, 0, 'plain', '', 0, 0, 'info'),
(128, 'pinterest_q3_20252', 'marketing', 'en_US', 'More visibility, smarter campaigns', 'Connect your store to Pinterest via the Conversions API, a new feature in the latest version of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Get started today — connect and sync your catalog using the Conversions API.', '{}', 'pending', 'woocommerce.com', '2025-09-24 17:39:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(129, 'pinterest_q4_2025', 'marketing', 'en_US', 'Maximize conversions with Pinterest', 'Connect your store to Pinterest via the Conversions API, now part of our official extension. Target the right shoppers, track performance, and optimize campaigns for more sales. Sync your catalog and create your first ad today.', '{}', 'pending', 'woocommerce.com', '2025-10-22 17:51:20', NULL, 0, 'plain', '', 0, 0, 'info'),
(130, 'paypaladvantage_q4_2025', 'marketing', 'en_US', 'PayPal Checkout offer: Get 40% back on fees for 3 months', 'Download and activate PayPal Payments in your WooCommerce admin, then complete your first transaction by 15 December 2025 to get 40% back on PayPal transaction fees — up to £2,000 for 3 months. PayPal Checkout works with your existing checkout. See terms: paypal.com/uk/campaign/paypalmerchantpromotion/terms.', '{}', 'pending', 'woocommerce.com', '2025-11-05 18:11:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(131, 'reddit_q4_2025', 'marketing', 'en_US', 'New: Reach high-intent shoppers on Reddit', 'Sync your catalog and pixel with Reddit for WooCommerce. Launch your ads faster on Reddit and connect with their 400M+ weekly active users and shoppers who turn to this platform for authentic conversations and recommendations.', '{}', 'pending', 'woocommerce.com', '2025-11-13 17:51:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(132, 'bfcm_general_sale_q4_2025', 'marketing', 'en_US', 'Save up to 40% on extensions and themes', 'For a limited time, take up to 40% off nearly everything in our Marketplace. It’s the perfect moment to give your store a holiday boost and level up for 2026. Sale ends December 2, 2025, at 14:00 UTC.', '{}', 'pending', 'woocommerce.com', '2025-11-19 17:48:56', NULL, 0, 'plain', '', 0, 0, 'info'),
(133, 'paypal-carding-recaptcha-dec-25', 'update', 'en_US', 'Activate PayPal fraud management', 'PayPal detected increased suspicious card activity in market. Please enable fraud protection in your PayPal Payment settings by enabling CAPTCHA for PayPal Payments.', '{}', 'pending', 'woocommerce.com', '2025-12-04 17:50:55', NULL, 0, 'plain', '', 0, 0, 'info'),
(134, 'Googleupdate_q4_2025', 'marketing', 'en_US', 'Make every ad dollar count this holiday season', 'Google for WooCommerce now includes Budget Recommendations. Install the latest version and get personalized suggestions on where to optimize campaign budgets to reach more holiday shoppers this season.', '{}', 'pending', 'woocommerce.com', '2025-12-05 17:47:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(135, 'holiday_shipping_deadlines_WCST_2025', 'marketing', 'en_US', 'Holiday shipping deadlines', 'Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.', '{}', 'pending', 'woocommerce.com', '2025-12-11 17:40:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(136, 'holiday_shipping_deadlines_WCS_2025', 'marketing', 'en_US', 'Holiday shipping deadlines', 'Ensure your packages arrive before December 25. Verify your exact ship-by date for your destination, carrier, and mail class.', '{}', 'pending', 'woocommerce.com', '2025-12-11 17:40:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(137, 'stripe_agenticcommerce_3PDS_q4_2025', 'marketing', 'en_US', 'Get more from Stripe with the official extension', 'Switch to the official extension co-developed with Stripe for the latest features and best performance. Get access to personalized checkout options, early support for AI shopping through Stripe’s <a href=\"https://woocommerce.com/posts/stripe-agentic-commerce-suite-for-woocommerce/\">Agentic Commerce Suite</a>, and more.', '{}', 'pending', 'woocommerce.com', '2025-12-18 17:38:47', NULL, 0, 'plain', '', 0, 0, 'info'),
(138, 'snap_q4_2025', 'marketing', 'en_US', 'New: Reach a new audience on Snapchat', '88% of Snapchatters love to shop, and 40% aren\'t active on other social platforms. Connect with them and grow your business using Snapchat for WooCommerce, our new official extension. Sync your products, launch ad campaigns, and track results — all from your Woo dashboard.', '{}', 'pending', 'woocommerce.com', '2025-12-19 17:38:32', NULL, 0, 'plain', '', 0, 0, 'info'),
(139, 'WC10.4.3-security-update-12-22-2025', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>Please update to WooCommerce 10.4.3 to resolve a security issue.</strong> This update addresses an issue with the WooCommerce Store API that may have made guest order information visible to other logged in users. See the <a href=\"https://developer.woocommerce.com/2025/12/22/store-api-vulnerability-patched-in-woocommerce-8-1/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2025-12-22 17:39:00', NULL, 0, 'plain', '', 0, 0, 'info'),
(140, 'downloads-sub-Jan2026-RIN', 'marketing', 'en_US', 'WooCommerce Subscription Downloads is now part of WooCommerce Subscriptions', 'WooCommerce Subscriptions now allows you to include simple and variable downloadable products with your subscriptions. Streamline your subscription downloads by updating to the latest version of WooCommerce Subscriptions today.', '{}', 'pending', 'woocommerce.com', '2026-01-07 17:45:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(141, 'paypal-carding-recaptcha-jan-26', 'update', 'en_US', 'Fraud protection is now required — enable today', 'Card networks like Visa and Mastercard now require fraud prevention controls, and non-compliance may result in fines and processing restrictions. Please enable reCAPTCHA in your PayPal Payments settings to help protect your store and maintain compliance.', '{}', 'pending', 'woocommerce.com', '2026-01-13 17:43:10', NULL, 0, 'plain', '', 0, 0, 'info'),
(142, 'USPS API Migration_RIN_Jan2026', 'marketing', 'en_US', 'Upgrade to USPS Shipping REST API by January 25', 'USPS is retiring the legacy Web Tools API on January 25, 2026. If you’re using the USPS Shipping Method extension with the legacy API, live USPS shipping rates will longer be shown at checkout. Migrate to the REST API now to avoid disruption.', '{}', 'pending', 'woocommerce.com', '2026-01-14 17:48:48', NULL, 0, 'plain', '', 0, 0, 'info'),
(143, 'existing_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Your Square POS can now accept in-person bitcoin payments, with near-instant settlement and no chargebacks. Enable it today and pay zero fees through 2026. T&amp;Cs apply.', '{}', 'pending', 'woocommerce.com', '2026-01-22 18:07:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(144, 'prospects_square_bitcoin_promotion_q1_2026', 'marketing', 'en_US', 'Take bitcoin payments in Square with 0% fees in 2026', 'Accept in-person <a href=\"https://woocommerce.com/posts/square-bitcoin-launch\">bitcoin payments</a> with Square POS — and pay zero fees on all bitcoin transactions through 2026. Get near-instant settlement and total protection from chargebacks.', '{}', 'pending', 'woocommerce.com', '2026-01-22 18:07:03', NULL, 0, 'plain', '', 0, 0, 'info'),
(145, 'wc-admin-orders-milestone', 'info', 'en_US', 'First order received', 'Congratulations on getting your first order! Now is a great time to learn how to manage your orders.', '{\"current_milestone\":1}', 'unactioned', 'woocommerce-admin', '2026-01-31 01:40:25', NULL, 0, 'plain', '', 0, 1, 'info'),
(146, 'reddit_q1_2026', 'marketing', 'en_US', 'Start advertising on Reddit with a $500 bonus', 'Make the most of our new Reddit integration with $500 in Reddit Ads! For a limited time, new advertisers who spend $500 in Reddit Ads Manager over 30 days will get $500 in ad credit. Your bonus credit unlocks automatically when you hit $500 in spend. Use your credit within 30 days.', '{}', 'pending', 'woocommerce.com', '2026-02-05 17:39:34', NULL, 0, 'plain', '', 0, 0, 'info'),
(147, 'Googleupdate_q1_2026', 'marketing', 'en_US', 'Make every ad dollar count', 'Google for WooCommerce now includes Budget Recommendations. Promote your products across Google — from Search to YouTube and beyond — and get personalized suggestions on where to optimize campaign budgets to reach more shoppers.', '{}', 'pending', 'woocommerce.com', '2026-02-11 17:38:30', NULL, 0, 'plain', '', 0, 0, 'info'),
(148, 'Mailchimp-API-maintenance-feb-2026', 'update', 'en_US', 'Mailchimp Maintenance Feb 28', 'Mailchimp will be carrying out planned API maintenance on February 28 from 11am – 4pm EST. During that time, you may see brief sync interruptions in Mailchimp for WooCommerce. Most data will catch up automatically. See the <a href=\"https://developer.woocommerce.com/2026/02/27/mailchimp-api-maintenance-february-28/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'pending', 'woocommerce.com', '2026-02-27 17:51:28', NULL, 0, 'plain', '', 0, 0, 'info'),
(149, 'RIN-WC-Security-Update-admin-update-March-2026', 'update', 'en_US', 'An important update is required for WooCommerce', '<strong>Update to WooCommerce 10.5.3 or the latest version to resolve a security issue.</strong> This update addresses a vulnerability in WooCommerce versions 5.4 to 10.5.2 that could have permitted unauthorized admin account access. See the <a href=\"https://developer.woocommerce.com/2026/03/02/store-api-vulnerability-patched-in-woocommerce-5-4/\" target=\"_blank\">Woo Developer blog</a> for more information.', '{}', 'unactioned', 'woocommerce.com', '2026-03-03 17:49:29', NULL, 0, 'plain', '', 1, 0, 'info'),
(150, 'USPS_Scan_Form_Mar2026', 'marketing', 'en_US', 'New: Save time shipping with USPS SCAN Form', 'USPS SCAN Form consolidates multiple shipments into one scannable sheet. Hand off all your orders at once — no more scanning packages individually. Select “Create SCAN Form” under your orders to try it today.', '{}', 'pending', 'woocommerce.com', '2026-03-11 17:38:15', NULL, 0, 'plain', '', 0, 0, 'info'),
(151, 'usps-surcharge-apr2026', 'marketing', 'en_US', 'Heads up: USPS rates increasing 8% on April 26', 'USPS is adding a temporary 8% surcharge on Priority Mail, Priority Mail Express, Ground Advantage, and Parcel Select from April 26, 2026 through January 17, 2027. WooCommerce Shipping discounted rates still apply.', '{}', 'pending', 'woocommerce.com', '2026-04-22 17:40:28', NULL, 0, 'plain', '', 0, 0, 'info'),
(152, 'stripe-woo-gateway-update-april2026', 'update', 'en_US', 'A critical update is required for Stripe for WooCommerce', '<strong>A critical update is required for Stripe for WooCommerce</strong> that addresses possible payment issues. Please update the WooCommerce Stripe Gateway to v10.6.1 immediately.', '{}', 'pending', 'woocommerce.com', '2026-04-24 17:37:39', NULL, 0, 'plain', '', 0, 0, 'info'),
(153, 'klaviyo_q2_2026', 'marketing', 'en_US', 'Attn Woo: Klaviyo Customer Hub is here', 'Drive revenue and reduce your support burden by giving customers a single place to manage their orders, returns, subscriptions, loyalty, and more. Enable Customer Hub in your Klaviyo dashboard today, available on all paid plans.', '{}', 'pending', 'woocommerce.com', '2026-04-30 17:58:27', NULL, 0, 'plain', '', 0, 0, 'info'),
(154, 'existing_square_discountcodes_gtm_q2_2026', 'marketing', 'en_US', 'Automatic coupon sync now available in Square', 'The discount codes you create in your Square dashboard will now work directly on your WooCommerce checkout — no need to manually sync coupons. Manage all of your discounts from one place with automatic redemption count updates.', '{}', 'pending', 'woocommerce.com', '2026-05-14 17:48:26', NULL, 0, 'plain', '', 0, 0, 'info'),
(155, 'prospects_square_discountcodes_gtm_q2_2026', 'marketing', 'en_US', 'Square now offers automatic coupon sync', 'Big news for smoother cross-channel sales: you can now create discount codes in Square and have them work directly at checkout on your Woo store, no manual sync required. Save time when you manage your discounts from one place — and keep your online and in-person sales seamlessly connected.', '{}', 'pending', 'woocommerce.com', '2026-05-18 17:45:12', NULL, 0, 'plain', '', 0, 0, 'info'),
(156, 'paypal_bnpl_mx_promo_Q2_2026', 'marketing', 'en_US', 'Bigger carts, lower fees: enable installments today', 'Merchants using PayPal installments see up to 205% higher average order values. Activate 3-installment payments from your PayPal Business dashboard and get 30% off transaction fees for 90 days. Sign up by October 15, 2026. Limited availability. Terms apply.', '{}', 'pending', 'woocommerce.com', '2026-05-20 17:38:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(157, 'stripe_adaptivepricing_q2_2026', 'marketing', 'en_US', 'Sell internationally with Adaptive Pricing from Stripe', 'Adaptive Pricing is now available in the official Stripe for WooCommerce extension. Show prices in local currency across 150+ countries, lifting cross-border revenue by 17.8%. Shoppers pay exactly what they see at checkout, while you settle in your base currency.', '{}', 'pending', 'woocommerce.com', '2026-05-28 17:40:02', NULL, 0, 'plain', '', 0, 0, 'info'),
(158, 'woo-dotcom-course-2026-06-09', 'marketing', 'en_US', 'Learn how to build your store with WooCommerce', 'In this free course, we\'ll help you set up and run your online store with clear, practical guidance.', '{}', 'pending', 'woocommerce.com', '2026-06-09 17:39:46', NULL, 0, 'plain', '', 0, 0, 'info'),
(159, 'google for woocommerce-Q2 2026-CYO', 'marketing', 'en_US', 'Limited-time offer: Get 2x your ad spend back in Google Ads', 'New to Google Ads and based in the US? Launch your first Google Ads campaign before June 30 to receive double your ad spend back as Google Ads credit.  \r\n\r\nUse new GenAI tools, YouTube Shopping, and Performance Max campaigns to sell more with WooCommerce and Google — get started today.', '{}', 'pending', 'woocommerce.com', '2026-06-12 17:38:42', NULL, 0, 'plain', '', 0, 0, 'info'),
(160, 'googleforwoocommerce_q2_2026', 'marketing', 'en_US', 'Limited-time offer: Get 2x your ad spend back in Google Ads', 'New to Google Ads and based in the US? Launch your first Google Ads campaign before June 30 to receive double your ad spend back as Google Ads credit.  \r\n\r\nUse new GenAI tools, YouTube Shopping, and Performance Max campaigns to sell more with WooCommerce and Google — get started today.', '{}', 'pending', 'woocommerce.com', '2026-06-13 17:41:33', NULL, 0, 'plain', '', 0, 0, 'info'),
(161, 'APFS-consolidation-jun-26', 'marketing', 'en_US', 'New features in WooCommerce Subscriptions', 'All Products for WooCommerce Subscriptions is now included in WooCommerce Subscriptions — no extra extension required. Create multiple plans for a single product and turn one-time purchases into recurring revenue. Update Subscriptions to version 9.0 to get started.', '{}', 'pending', 'woocommerce.com', '2026-06-23 17:46:37', NULL, 0, 'plain', '', 0, 0, 'info'),
(162, 'paypal_q3_2026', 'marketing', 'en_US', 'Important update to your Braintree integration', 'PayPal Enterprise Payments (formerly Braintree) is now officially owned by Woo. This change brings UI improvements, a long-term roadmap, and active updates from the Woo team, with guaranteed compatibility so your payments never miss a beat.', '{}', 'pending', 'woocommerce.com', '2026-07-09 17:44:44', NULL, 0, 'plain', '', 0, 0, 'info'),
(163, 'gla-complete-setup', 'info', 'en_US', 'Reach more shoppers with product feed on Google', 'Finish setting up Google for WooCommerce to list your products on Google for free and promote them with ads.', '{}', 'unactioned', 'gla', '2026-07-12 07:53:56', NULL, 0, 'plain', '', 0, 1, 'info'),
(164, 'wc-admin-email-improvements', 'info', 'en_US', 'Store emails have had an upgrade!', 'We’ve made some exciting improvements to our email templates, including modern, shopper-friendly designs and new customization options. And if you’re using a block theme, you can automatically sync your theme styles! Head to your email settings to explore the new features.', '{}', 'unactioned', 'woocommerce-admin', '2026-07-12 17:38:39', NULL, 0, 'plain', '', 0, 1, 'info'),
(165, 'wc-admin-scheduled-updates-promotion', 'info', 'en_US', 'Analytics now supports scheduled updates', 'This provides improved performance to your store, enable it in Analytics &gt; Settings.', '{}', 'unactioned', 'woocommerce-admin', '2026-07-12 17:38:40', NULL, 0, 'plain', '', 0, 1, 'info'),
(166, 'stripe-woo-gateway-update-july2026', 'update', 'en_US', 'An important update is required for Stripe for WooCommerce', '<strong>A critical update is required for Stripe for WooCommerce</strong> to address an issue that could lead to fraudulent payment totals. Please update your extension to the latest version immediately.', '{}', 'pending', 'woocommerce.com', '2026-07-19 03:36:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(167, '3pdmigration_paytrace_fortis', 'marketing', 'en_US', 'Important update about your Paytrace Gateway', 'Paytrace Gateway is being phased out of the WooCommerce.com Marketplace. Nothing changes right now, and your store will continue to work as usual. You’ll receive a retirement notice closer to the date. When you\'re ready to migrate, we recommend Fortis Payments — their team offers step-by-step migration guidance to help', '{}', 'pending', 'woocommerce.com', '2026-07-19 03:36:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(168, '3pdmigration_paytrace_visa', 'marketing', 'en_US', 'Important update about your Paytrace Gateway', 'Paytrace Gateway is being phased out of the WooCommerce.com Marketplace. Nothing changes right now, and your store will continue to work as usual. You’ll receive a retirement notice closer to the date. As a replacement, we recommend Visa Acceptance Solutions — accept popular payment methods in 97% of territories.', '{}', 'pending', 'woocommerce.com', '2026-07-19 03:36:24', NULL, 0, 'plain', '', 0, 0, 'info'),
(169, 'googleforwoocommerce_q2_2026_row_incentive', 'marketing', 'en_US', 'Choose one of three Google Ads signup offers', 'New to Google Ads? Launch your first campaign and get a budget boost with one of three signup offers. Choose the offer that fits your monthly budget and start reaching more customers in more places. Offer for new advertisers only. Terms apply.', '{}', 'pending', 'woocommerce.com', '2026-07-23 04:02:53', NULL, 0, 'plain', '', 0, 0, 'info'),
(170, 'mollie_incentive_h2_2026_PL', 'marketing', 'en_US', 'Localize your checkout with Mollie Payments', 'Boost conversions with BLIK and Przelewy24, alongside Europe’s most popular options, with Mollie’s smooth and reliable checkout experience. Sign up today and process up to PLN 50 000 with 0% fees until December 31. Terms and conditions apply.', '{}', 'pending', 'woocommerce.com', '2026-07-23 04:02:53', NULL, 0, 'plain', '', 0, 0, 'info'),
(171, 'klaviyo_q3_2026', 'marketing', 'en_US', 'Attn Woo: Klaviyo Customer Hub is here', 'Drive revenue and reduce your support burden by giving customers a single place to manage their orders, returns, subscriptions, loyalty, and more. Enable Customer Hub in your Klaviyo dashboard today, available on all paid plans.', '{}', 'pending', 'woocommerce.com', '2026-07-30 04:19:09', NULL, 0, 'plain', '', 0, 0, 'info'),
(172, 'woo-subscriptions-update-august2026', 'update', 'en_US', 'Please update WooCommerce Subscriptions now', '<strong>The latest version of WooCommerce Subscriptions includes important security updates.</strong> Please update immediately to ensure your store is protected.', '{}', 'pending', 'woocommerce.com', '2026-08-06 05:51:51', NULL, 0, 'plain', '', 0, 0, 'info'),
(173, 'woocommerce-stripe-update-aug2026', 'update', 'en_US', 'An important update is required for Stripe for WooCommerce', '<strong>There is a critical security update available for Stripe for WooCommerce.</strong> Please update to the latest version immediately.', '{}', 'pending', 'woocommerce.com', '2026-08-07 06:01:56', NULL, 0, 'plain', '', 0, 0, 'info'),
(174, 'fedex-ga-launch-wcs-aug26', 'marketing', 'en_US', 'WooCommerce Shipping now supports FedEx services', 'You can now give customers the speed and convenience of FedEx right from your store dashboard — with no minimum volume requirements. Offer popular domestic and international options, access discounted rates, and simplify your workflow when you ship FedEx on WooCommerce Shipping.', '{}', 'pending', 'woocommerce.com', '2026-08-07 06:01:56', NULL, 0, 'plain', '', 0, 0, 'info'),
(175, 'fedex-ga-wcst-aug26', 'marketing', 'en_US', 'WooCommerce Shipping now supports FedEx services', 'You can now give customers the speed and convenience of FedEx right from your store dashboard — with no minimum volume requirements. Offer popular domestic and international options, access discounted rates, and simplify your workflow when you ship FedEx on WooCommerce Shipping.', '{}', 'pending', 'woocommerce.com', '2026-08-07 06:01:56', NULL, 0, 'plain', '', 0, 0, 'info');
